diff --git a/applets/cameraindicator/cameradevicemonitor.cpp b/applets/cameraindicator/cameradevicemonitor.cpp
new file mode 100644
index 0000000000..fa2617f4bb
--- /dev/null
+++ b/applets/cameraindicator/cameradevicemonitor.cpp
@@ -0,0 +1,198 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "cameradevicemonitor.h"
+
+#include <QDir>
+#include <QFile>
+#include <QFileInfo>
+
+#include <sys/inotify.h>
+#include <unistd.h>
+
+using namespace Qt::StringLiterals;
+
+namespace
+{
+const QString s_devDir = u"/dev"_s;
+const QString s_videoPrefix = u"video"_s;
+
+// Matches NodeState::Running in KPipeWire's MediaMonitor
+constexpr int s_runningState = 3;
+
+// These processes open the devices on behalf of PipeWire clients, which MediaMonitor already shows
+bool isPipeWireProcess(const QString &procDir)
+{
+    QFile file(procDir + u"/comm");
+    if (!file.open(QIODevice::ReadOnly)) {
+        return false;
+    }
+    const QByteArray comm = file.readAll().trimmed();
+    return comm == "pipewire" || comm == "wireplumber" || comm == "pipewire-media-session";
+}
+}
+
+CameraDeviceMonitor::CameraDeviceMonitor(QObject *parent)
+    : QAbstractListModel(parent)
+{
+    m_scanTimer.setSingleShot(true);
+    m_scanTimer.setInterval(250);
+    connect(&m_scanTimer, &QTimer::timeout, this, &CameraDeviceMonitor::scan);
+
+    m_inotifyFd = inotify_init1(IN_NONBLOCK | IN_CLOEXEC);
+    if (m_inotifyFd < 0) {
+        return;
+    }
+    m_notifier = new QSocketNotifier(m_inotifyFd, QSocketNotifier::Read, this);
+    connect(m_notifier, &QSocketNotifier::activated, this, &CameraDeviceMonitor::readEvents);
+
+    const int wd = inotify_add_watch(m_inotifyFd, QFile::encodeName(s_devDir).constData(), IN_CREATE | IN_DELETE | IN_ONLYDIR);
+    if (wd >= 0) {
+        m_watches.insert(wd, QString());
+    }
+    updateWatches();
+    scan();
+}
+
+CameraDeviceMonitor::~CameraDeviceMonitor()
+{
+    if (m_inotifyFd >= 0) {
+        close(m_inotifyFd);
+    }
+}
+
+void CameraDeviceMonitor::readEvents()
+{
+    alignas(inotify_event) char buffer[4096];
+    bool devicesChanged = false;
+    bool usageChanged = false;
+
+    ssize_t length;
+    while ((length = read(m_inotifyFd, buffer, sizeof(buffer))) > 0) {
+        for (char *ptr = buffer; ptr < buffer + length;) {
+            const auto event = reinterpret_cast<const inotify_event *>(ptr);
+            ptr += sizeof(inotify_event) + event->len;
+
+            if (event->mask & IN_IGNORED) {
+                m_watches.remove(event->wd);
+                usageChanged = true;
+            } else if (event->mask & (IN_CREATE | IN_DELETE)) {
+                if (event->len > 0 && QFile::decodeName(event->name).startsWith(s_videoPrefix)) {
+                    devicesChanged = true;
+                }
+            } else {
+                usageChanged = true;
+            }
+        }
+    }
+
+    if (devicesChanged) {
+        updateWatches();
+    }
+    if (devicesChanged || usageChanged) {
+        m_scanTimer.start();
+    }
+}
+
+void CameraDeviceMonitor::updateWatches()
+{
+    const QStringList entries = QDir(s_devDir).entryList({s_videoPrefix + u'*'}, QDir::System);
+    for (const QString &entry : entries) {
+        const QString path = s_devDir + u'/' + entry;
+        if (std::ranges::find(std::as_const(m_watches), path) != m_watches.cend()) {
+            continue;
+        }
+        const int wd = inotify_add_watch(m_inotifyFd, QFile::encodeName(path).constData(), IN_OPEN | IN_CLOSE);
+        if (wd >= 0) {
+            m_watches.insert(wd, path);
+        }
+    }
+}
+
+void CameraDeviceMonitor::scan()
+{
+    QStringList paths;
+
+    const QStringList pids = QDir(u"/proc"_s).entryList(QDir::Dirs | QDir::NoDotAndDotDot);
+    for (const QString &pid : pids) {
+        bool isPid = false;
+        pid.toInt(&isPid);
+        if (!isPid) {
+            continue;
+        }
+        const QString procDir = u"/proc/"_s + pid;
+        const QDir fdDir(procDir + u"/fd"_s);
+        // Fails for other users' processes
+        const QStringList fds = fdDir.entryList(QDir::System | QDir::NoDotAndDotDot);
+        QStringList processPaths;
+        for (const QString &fd : fds) {
+            const QString target = QFile::symLinkTarget(fdDir.filePath(fd));
+            if (target.startsWith(s_devDir + u'/' + s_videoPrefix) && !paths.contains(target) && !processPaths.contains(target)) {
+                processPaths.append(target);
+            }
+        }
+        if (!processPaths.isEmpty() && !isPipeWireProcess(procDir)) {
+            paths.append(processPaths);
+        }
+    }
+    paths.sort();
+
+    QList<Device> devices;
+    devices.reserve(paths.size());
+    for (const QString &path : std::as_const(paths)) {
+        QFile nameFile(u"/sys/class/video4linux/"_s + QFileInfo(path).fileName() + u"/name"_s);
+        QString name;
+        if (nameFile.open(QIODevice::ReadOnly)) {
+            name = QString::fromUtf8(nameFile.readAll().trimmed());
+        }
+        devices.append({path, name});
+    }
+
+    const bool changed = !std::ranges::equal(devices, m_devices, [](const Device &a, const Device &b) {
+        return a.path == b.path && a.name == b.name;
+    });
+    if (!changed) {
+        return;
+    }
+    const bool countChanged = devices.size() != m_devices.size();
+    beginResetModel();
+    m_devices = devices;
+    endResetModel();
+    if (countChanged) {
+        Q_EMIT this->countChanged();
+    }
+}
+
+QVariant CameraDeviceMonitor::data(const QModelIndex &index, int role) const
+{
+    if (!checkIndex(index, CheckIndexOption::IndexIsValid | CheckIndexOption::ParentIsInvalid)) {
+        return {};
+    }
+    const Device &device = m_devices.at(index.row());
+    switch (role) {
+    case Qt::DisplayRole:
+        return device.name.isEmpty() ? device.path : device.name;
+    case StateRole:
+        return s_runningState;
+    default:
+        return {};
+    }
+}
+
+int CameraDeviceMonitor::rowCount(const QModelIndex &parent) const
+{
+    return parent.isValid() ? 0 : m_devices.size();
+}
+
+QHash<int, QByteArray> CameraDeviceMonitor::roleNames() const
+{
+    return {
+        {Qt::DisplayRole, QByteArrayLiteral("display")},
+        {StateRole, QByteArrayLiteral("state")},
+    };
+}
+
+#include "moc_cameradevicemonitor.cpp"
