+*/
+
+#pragma once
+
+#include <QAbstractListModel>
+#include <QHash>
+#include <QSocketNotifier>
+#include <QTimer>
+
+#include <qqmlregistration.h>
+
+/**
+ * Lists the V4L2 video devices (/dev/video*) that processes of the current
+ * user hold open directly, without going through PipeWire.
+ */
+class CameraDeviceMonitor : public QAbstractListModel
+{
+    Q_OBJECT
+    QML_ELEMENT
+
+    Q_PROPERTY(int count READ rowCount NOTIFY countChanged)
+
+public:
+    // Same roles as KPipeWire's MediaMonitor, so both can be shown in one list
+    enum Role {
+        StateRole = Qt::UserRole + 1,
+    };
+    Q_ENUM(Role)
+
+    explicit CameraDeviceMonitor(QObject *parent = nullptr);
+    ~CameraDeviceMonitor() override;
+
+    QVariant data(const QModelIndex &index, int role) const override;
+    int rowCount(const QModelIndex &parent = QModelIndex()) const override;
+    QHash<int, QByteArray> roleNames() const override;
+
+Q_SIGNALS:
+    void countChanged();
+
+private:
+    struct Device {
+        QString path;
+        QString name;
+    };
+
+    void readEvents();
+    void updateWatches();
+    void scan();
+
+    int m_inotifyFd = -1;
+    QSocketNotifier *m_notifier = nullptr;
+    QHash<int, QString> m_watches;
+    QTimer m_scanTimer;
+    QList<Device> m_devices;
+};
diff --git a/applets/cameraindicator/cameramodel.cpp b/applets/cameraindicator/cameramodel.cpp
