+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "cameramodel.h"
+
+CameraModel::CameraModel(QObject *parent)
+    : QConcatenateTablesProxyModel(parent)
+{
+    connect(this, &QAbstractItemModel::rowsInserted, this, &CameraModel::countChanged);
+    connect(this, &QAbstractItemModel::rowsRemoved, this, &CameraModel::countChanged);
+    connect(this, &QAbstractItemModel::modelReset, this, &CameraModel::countChanged);
+    connect(this, &QAbstractItemModel::layoutChanged, this, &CameraModel::countChanged);
+}
+
+void CameraModel::setSources(const QList<QAbstractItemModel *> &sources)
+{
+    if (sources == sourceModels()) {
+        return;
+    }
+    const QList<QAbstractItemModel *> oldSources = sourceModels();
+    for (QAbstractItemModel *source : oldSources) {
+        removeSourceModel(source);
+    }
+    for (QAbstractItemModel *source : sources) {
+        if (source) {
+            addSourceModel(source);
+        }
+    }
+    Q_EMIT sourcesChanged();
+    Q_EMIT countChanged();
+}
+
+int CameraModel::count() const
+{
+    return rowCount();
+}
+
+#include "moc_cameramodel.cpp"
