+
+public:
+    explicit CameraModel(QObject *parent = nullptr);
+
+    void setSources(const QList<QAbstractItemModel *> &sources);
+    int count() const;
+
+Q_SIGNALS:
+    void sourcesChanged();
+    void countChanged();
+};
